import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"kernl","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1793722866000}'),s={name:"index.md"};function n(d,e,h,i,l,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="kernl" tabindex="-1">kernl <a class="header-anchor" href="#kernl" aria-label="Permalink to &quot;kernl&quot;">​</a></h1><p>kernl is an opinionated shell for sandboxed web applets. It is built on <a href="https://github.com/kehto/web" target="_blank" rel="noreferrer">kehto</a>, the unopinionated NIP-5D toolkit, and it treats the person at the keyboard as the only principal who matters.</p><p>A shell has two jobs. It gives the user a place where their identity, relays, contacts, media and messages are theirs and portable. And it gives an untrusted program a place to run where the worst it can do is bounded. kernl does both, and when kehto offers a way to bound an applet further, kernl turns it on by default.</p><div class="warning custom-block"><p class="custom-block-title">Alpha</p><p>kernl is a first draft. The four packages build, the contracts are stable enough to document, and the shell runs. Several backends are contracts without implementations. Read <a href="./alpha-status">Alpha status</a> before depending on anything here.</p></div><h2 id="what-kernl-decides-that-kehto-leaves-open" tabindex="-1">What kernl decides that kehto leaves open <a class="header-anchor" href="#what-kernl-decides-that-kehto-leaves-open" aria-label="Permalink to &quot;What kernl decides that kehto leaves open&quot;">​</a></h2><p>kehto ships <code>@kehto/{acl,firewall,runtime,shell,services,nip,wm}</code> and deliberately does not pick a relay library, a signer, a consent model, a layout engine or a deployment story. kernl picks all of them:</p><table tabindex="0"><thead><tr><th>Opinion</th><th>kernl&#39;s choice</th></tr></thead><tbody><tr><td>Event layer</td><td><a href="https://applesauce.build" target="_blank" rel="noreferrer">applesauce</a> v7 only. One <code>EventStore</code>, one <code>RelayPool</code>, one <code>AccountManager</code> per shell. <code>nostr-tools</code> is never imported by kernl source.</td></tr><tr><td>Containment</td><td>Opaque-origin <code>srcdoc</code> iframe, <code>sandbox=&quot;allow-scripts&quot;</code>, zero-network CSP, every network path through a shell service the user can see, rate-limit and revoke.</td></tr><tr><td>Mitigations</td><td>Every kehto mitigation ships on, in the <code>strict</code> <a href="./concepts/guard">guard</a> profile. The user loosens per applet; a developer never loosens globally.</td></tr><tr><td>Protocols</td><td>One identity layer, many <a href="./concepts/bridges">bridges</a> named by what they do for the user, never by the wire format.</td></tr><tr><td>Messaging</td><td>Any reasonable private-messaging protocol, exposed through one contract. <a href="./concepts/messaging">Providers</a> describe their security properties truthfully and the shell does not rank them.</td></tr></tbody></table><p>kernl does not fork kehto. When kehto lacks a hook kernl needs, kernl composes around it and files the gap upstream. The four gaps filed so far are recorded in <a href="./alpha-status#upstream-gaps">D-001</a>.</p><h2 id="three-doors" tabindex="-1">Three doors <a class="header-anchor" href="#three-doors" aria-label="Permalink to &quot;Three doors&quot;">​</a></h2><p><strong>Use the shell.</strong> Run kernl locally, sign in with a browser extension or a remote signer, and open an applet by its address. Start with <a href="./tutorials/run-the-shell">Run the shell</a>, then read <a href="./how-tos/grant-and-revoke">Grant and revoke</a> to understand what the shell asks you and why.</p><p><strong>Build an applet for it.</strong> Applets are ordinary NIP-5D napplets; kernl adds nothing to the wire format. What kernl changes is the posture: fewer domains advertised until granted, deferral while hidden, and rate limits that tighten when you lose focus. <a href="./tutorials/build-an-applet-for-kernl">Build an applet for kernl</a> tells you what to expect and how to test against it.</p><p><strong>Extend the shell.</strong> Add a <a href="./how-tos/add-a-messaging-provider">messaging provider</a>, a <a href="./how-tos/add-a-bridge-backend">bridge backend</a>, or change how the guard is composed. Start with <a href="./concepts/architecture">Architecture</a> and the <a href="./packages/">package pages</a>.</p><h2 id="how-these-docs-are-organised" tabindex="-1">How these docs are organised <a class="header-anchor" href="#how-these-docs-are-organised" aria-label="Permalink to &quot;How these docs are organised&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Section</th><th>What you find there</th></tr></thead><tbody><tr><td><a href="./concepts/architecture">Concepts</a></td><td>Why the shell is shaped the way it is: layering, guard, identity, messaging, bridges.</td></tr><tr><td><a href="./tutorials/run-the-shell">Tutorials</a></td><td>End-to-end walkthroughs that leave you with something running.</td></tr><tr><td><a href="./how-tos/change-guard-profile">How-tos</a></td><td>One task each, with the exact calls.</td></tr><tr><td><a href="./packages/">Packages</a></td><td>One page per published package: version, install, exports, scope.</td></tr><tr><td><a href="./reference/api">API reference</a></td><td>Generated from source JSDoc by TypeDoc.</td></tr><tr><td><a href="./policies/">Policies</a></td><td>Rules the repository enforces mechanically: vocabulary, security posture, spec conformance.</td></tr></tbody></table><p>Protocol vocabulary is used freely in these pages because they are written for developers. The public website and the shell UI follow a different rule, described in <a href="./policies/public-vocabulary">Public vocabulary</a>.</p><p>Agents reading this site should start at <a href="./agent-access">Agent access</a>.</p><h2 id="licence-and-cost" tabindex="-1">Licence and cost <a class="header-anchor" href="#licence-and-cost" aria-label="Permalink to &quot;Licence and cost&quot;">​</a></h2><p>kernl is free software under the MIT licence. Every package and the shell cost $0; there is no paid tier and no account to buy. The source, these docs and the decisions behind both live at <a href="https://github.com/kernlize/web" target="_blank" rel="noreferrer">kernlize/web</a>.</p>',18)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
